; b01_timers -- the Main timer and the Peri timer run side by side
; Layer-2 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: are MAIN_TIMER_DONE and IF_TIMER_DONE two timers or one (Q1); a start clears the done flag; a timer can be started again
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: b01_timers.expected.csv
.include "conf_defs.inc"
.include "conf_board.inc"                      ; the CSRs of the board: put YOUR addresses and bits there first
.equ T_SHORT = 2000                            ; ticks: Main waits this long, twice
.equ T_LONG  = 65000                           ; ticks: Peri waits this long, twice -- far longer than everything Main does first
.main
    EXEC_CSR WRITE8 MAIN_TPER,   T_SHORT & 0xFF
    EXEC_CSR WRITE8 MAIN_TPER_H, T_SHORT >> 8
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
m1:
    BR.COND MAIN_TIMER_DONE, m1_done
    JMP m1
m1_done:
    EXEC_CSR WRITE8 RES + 0, 0x11              ; Main's first short wait is over
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
m2:
    BR.COND MAIN_TIMER_DONE, m2_done
    JMP m2
m2_done:
    EXEC_CSR WRITE8 RES + 1, 0x12              ; ... and the second one
    EXEC_CSR WRITE8 MAIN_TPER,   T_LONG & 0xFF ; now three long waits, so that Main ends after Peri in every case
    EXEC_CSR WRITE8 MAIN_TPER_H, T_LONG >> 8
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
m3:
    BR.COND MAIN_TIMER_DONE, m3_done
    JMP m3
m3_done:
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
m4:
    BR.COND MAIN_TIMER_DONE, m4_done
    JMP m4
m4_done:
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
m5:
    BR.COND MAIN_TIMER_DONE, m5_done
    JMP m5
m5_done:
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
.peri
    EXEC_CSR SET8 PERI_CTRL, PERI_RESET
    EXEC_CSR WRITE8 PERI_TPER,   T_LONG & 0xFF
    EXEC_CSR WRITE8 PERI_TPER_H, T_LONG >> 8
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START
p1:
    BR.IF_TIMER_DONE p1_done
    JMP p1
p1_done:
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START
p2:
    BR.IF_TIMER_DONE p2_done
    JMP p2
p2_done:
    EXEC_CSR WRITE8 RES + 8, 0x21              ; Peri's two long waits are over
phalt:
    JMP phalt
